// Des: Parse command line: command, positional words, safety ladder flags
// Flo: scan argv > flags set mode (read, dry, live, force) > rest are words > typed usage error
// I/O: argv strings (caller) > Args struct (slices into argv)
// ===================================================================
const std = @import("std"); const logz = @import("lo-logz-line.zig"); const sess = @import("ru-sess-ctxz.zig");
pub const Args = struct { cmd: []const u8 = "help", rest: []const []const u8 = &.{}, json: bool = false, mode: sess.Mode = .dry, mock: bool = false, yes: bool = false, conf: []const u8 = "", acct: []const u8 = "", dryz: bool = false, helz: bool = false, bare: bool = false, sink: ?*std.ArrayList(u8) = null, pub fn quiet(self: Args) bool { return std.mem.eql(u8, self.cmd, "status") or std.mem.eql(u8, self.cmd, "caps"); } };
fn badz(what: []const u8, toke: []const u8) error{BadUsage} { logz.logz("args", .erro, what, toke, "run: za help"); return error.BadUsage; }
pub fn parse(aren: std.mem.Allocator, argv: []const []const u8) !Args { var out: Args = .{}; var words: std.ArrayList([]const u8) = .empty; var live = false; var forc = false; var read = false; var idx: usize = 0; while (idx < argv.len) : (idx += 1) { const itm = argv[idx]; if (std.mem.eql(u8, itm, "--json")) { out.json = true; } else if (std.mem.eql(u8, itm, "--mock")) { out.mock = true; } else if (std.mem.eql(u8, itm, "--yes")) { out.yes = true; } else if (std.mem.eql(u8, itm, "--dry") or std.mem.eql(u8, itm, "--dry-run")) { out.dryz = true; out.mode = .dry; } else if (std.mem.eql(u8, itm, "--help") or std.mem.eql(u8, itm, "-h")) { out.helz = true; } else if (std.mem.eql(u8, itm, "--read")) { read = true; } else if (std.mem.eql(u8, itm, "--live")) { live = true; } else if (std.mem.eql(u8, itm, "--force")) { forc = true; } else if (std.mem.eql(u8, itm, "--acct")) { idx += 1; if (idx >= argv.len) return badz("missing value after", itm); out.acct = argv[idx]; } else if (std.mem.eql(u8, itm, "--conf")) { idx += 1; if (idx >= argv.len) return badz("missing value after", itm); out.conf = argv[idx]; } else if (std.mem.startsWith(u8, itm, "--")) { return badz("unknown flag", itm); } else try words.append(aren, itm); } if (forc and !live) return badz("--force needs", "--live"); if (read and live) return badz("--read cannot be used with", "--live"); if (out.dryz and live) return badz("--dry-run and --live cannot be used", "together"); out.bare = words.items.len == 0; if (read) out.mode = .read; if (live) out.mode = if (forc) .force else .live; if (words.items.len > 0) { out.cmd = words.items[0]; out.rest = words.items[1..]; } return out; }
